import Foundation

/// Read-only access to the question bank shipped in the app bundle (`content.sqlite`).
/// The database is generated by `tools/content/build_content.py`; see that script
/// for the schema.
final class ContentStore {
    enum ContentError: Error, CustomStringConvertible {
        case missingBundleResource
        case incompatibleSchema(found: Int, expected: Int)

        var description: String {
            switch self {
            case .missingBundleResource:
                "The question bank (content.sqlite) is missing from the app bundle."
            case let .incompatibleSchema(found, expected):
                "The question bank has schema version \(found); this build expects \(expected)."
            }
        }
    }

    /// Bump together with `SCHEMA_VERSION` in `tools/content/build_content.py`.
    static let schemaVersion = 3

    let database: SQLiteDatabase

    init(url: URL) throws {
        database = try SQLiteDatabase(path: url.path, readOnly: true)
        let version = database.userVersion
        guard version == Self.schemaVersion else {
            throw ContentError.incompatibleSchema(found: version, expected: Self.schemaVersion)
        }
    }

    static func bundled(in bundle: Bundle = .main) throws -> ContentStore {
        guard let url = bundle.url(forResource: "content", withExtension: "sqlite") else {
            throw ContentError.missingBundleResource
        }
        return try ContentStore(url: url)
    }

    func makeProviders() throws -> [Topic: any QuestionProvider] {
        [
            .mentalMath: try MentalMathProvider(database: database),
            .geography: try GeographyProvider(database: database),
            .vocabulary: try VocabularyProvider(database: database),
        ]
    }
}
